import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.admin.organization.projects.rateLimits.updateRateLimit("project_id", "rate_limit_id", { max_requests_per_1_minute: 1, max_tokens_per_1_minute: 1, max_images_per_1_minute: 1, max_audio_megabytes_per_1_minute: 1, max_requests_per_1_day: 1, batch_1_day_max_input_tokens: 1 });
console.log(result);
